## Handling Multiple Parses

When you have several inputs, you parse each one and track what worked and what didn't.

### Parsing Three Numbers

```xiom
fn main() -> Int {
  let raw1 = "25";
  let raw2 = "bad";
  let raw3 = "100";

  let r1 = string.str_to_int(raw1);
  let r2 = string.str_to_int(raw2);
  let r3 = string.str_to_int(raw3);

  let success_count = 0;
  let sum = 0;

  match r1 {
    Ok(n) => { sum = sum + n; success_count = success_count + 1; },
    Err(e) => io.println("Field 1 error: " + e),
  };
  match r2 {
    Ok(n) => { sum = sum + n; success_count = success_count + 1; },
    Err(e) => io.println("Field 2 error: " + e),
  };
  match r3 {
    Ok(n) => { sum = sum + n; success_count = success_count + 1; },
    Err(e) => io.println("Field 3 error: " + e),
  };

  io.println("Successfully parsed: " + string.int_to_str(success_count));
  io.println("Sum: " + string.int_to_str(sum));
  return 0;
}
```

### Using a Helper Function

Rather than repeating match logic, extract a helper:

```xiom
fn check_field(raw: Str, label: Str) -> Result[Int, Str] {
  let parsed = string.str_to_int(raw);
  return match parsed {
    Ok(n) => Ok(n),
    Err(e) => Err(label + ": " + e),
  };
}

fn main() -> Int {
  let a = check_field("10", "Age");
  let b = check_field("xyz", "Score");
  let c = check_field("50", "Qty");

  let success = 0;
  let total = 0;

  match a { Ok(n) => { total = total + n; success = success + 1; } Err(_) => {} };
  match b { Ok(n) => { total = total + n; success = success + 1; } Err(_) => {} };
  match c { Ok(n) => { total = total + n; success = success + 1; } Err(_) => {} };

  io.println("Valid fields: " + string.int_to_str(success) + "/3");
  io.println("Total: " + string.int_to_str(total));
  return 0;
}
```

