  let inputs = "15";  // imagine 3 inputs in sequence
  let inputs2 = "bad";
  let inputs3 = "30";

  let good = 0;

  if let Ok(_) = string.str_to_int(inputs) { good = good + 1; }
  if let Ok(_) = string.str_to_int(inputs2) { good = good + 1; }
  if let Ok(_) = string.str_to_int(inputs3) { good = good + 1; }

  io.println("Valid: " + string.int_to_str(good) + "/3");
  return 0;
}
```

